# Find which id maps to "spirit", "will", "word" - let me check the actual ids
id_map = {f['id']: i for i, f in enumerate(faculties)}
print("Faculty IDs:", [f['id'] for f in faculties])

for fac_id, data in new_data.items():
    if fac_id in id_map:
        idx = id_map[fac_id]
        faculties[idx].update(data)
        print(f"Updated faculty: {fac_id}")
    else:
        print(f"WARNING: faculty id '{fac_id}' not found!")

with open('data/faculties.json', 'w', encoding='utf-8') as f:
    json.dump(faculties, f, ensure_ascii=False, indent=2)

